{"Channel": {"name": "planning-CollaborateForce", "channelID": "ch-abaix-c92927"}, "Message": {"User": {"userId": "eid_16935c12", "timestamp": "2026-06-20T17:31:00", "text": "I agree—CollaborateForce does seem to capture the essence of the product better. It’s a strong move!", "utterranceID": "20260620-1-0b3ee"}, "Reactions": []}, "ThreadReplies": [], "id": "20260620-1-0b3ee"}
