{"Channel": {"name": "planning-AIX", "channelID": "ch-g-aix-f0202d"}, "Message": {"User": {"userId": "slack_admin_bot", "timestamp": "2026-03-27T16:19:00", "text": "@eid_2d72674d, @eid_4f30e22e joined planning-AIX.", "utterranceID": "20260327-12-3b2cc"}, "Reactions": []}, "ThreadReplies": [], "id": "20260327-12-3b2cc"}
{"Channel": {"name": "planning-AIX", "channelID": "ch-g-aix-f0202d"}, "Message": {"User": {"userId": "eid_99835861", "timestamp": "2026-03-28T21:06:00", "text": "Hi team, several customers have reported positive things about AIX. It's great to see such feedback!", "utterranceID": "20260327-0-3ad5f"}, "Reactions": []}, "ThreadReplies": [], "id": "20260327-0-3ad5f"}
