{"Channel": {"name": "bug-alicetaylor-MonitorForce", "channelID": "ch-force-7ef125"}, "Message": {"User": {"userId": "eid_5b9ab912", "timestamp": "2026-07-30T09:15:00", "text": "Thanks, everyone! Let's keep the communication open. If you need any more details or run into roadblocks, just shout. 🙌", "utterranceID": "20260729-7-3e830"}, "Reactions": []}, "ThreadReplies": [], "id": "20260729-7-3e830"}
